    if row['value'] < sensor['low']:
        bad = 1
        deviation = sensor['low'] - row['value']
    else:
        if row['value'] > sensor['high']:
            bad = 1
            deviation = row['value'] - sensor['high']
    detail = detail + [{'id': row['id'], 'sensor': row['sensor'], 'value': row['value'], 'bad': bad, 'deviation': deviation}]
summary = []
for sensor in sorted(sensors, key=lambda x: x['id']):
    sensor_rows = [row for row in detail if row['sensor'] == sensor['id']]
    bad_rows = [row for row in sensor_rows if row['bad'] == 1]
    summary = summary + [{'sensor': sensor['id'], 'count': len(sensor_rows), 'bad': sum([row['bad'] for row in sensor_rows]), 'deviation': sum([row['deviation'] for row in sensor_rows]), 'bad_ids': [row['id'] for row in bad_rows]}]
